## 1. Формирование CSV (`ReadingHistoryCSV.swift`)

Этот файл использует только Foundation, поэтому подходит для пакета с логикой, где SwiftUI не подключают.

```swift
import Foundation

/// Одна строка истории чтения для экспорта. Простая копия данных сессии,
/// чтобы файл можно было собрать в фоне, не трогая исходные объекты.
public struct ReadingHistoryRecord: Sendable, Equatable {
    public var startedAt: Date
    public var duration: TimeInterval
    public var timeZoneIdentifier: String
    public var bookTitle: String
    public var bookAuthor: String

    public init(
        startedAt: Date,
        duration: TimeInterval,
        timeZoneIdentifier: String,
        bookTitle: String,
        bookAuthor: String
    ) {
        self.startedAt = startedAt
        self.duration = duration
        self.timeZoneIdentifier = timeZoneIdentifier
        self.bookTitle = bookTitle
        self.bookAuthor = bookAuthor
    }
}

public enum ReadingHistoryCSV {
    public enum Delimiter: String, Sendable {
        case comma = ","
        case semicolon = ";"

        /// Excel берёт разделитель из региональных настроек: где десятичная
        /// запятая (Россия, большая часть Европы), он ждёт точку с запятой.
        public static func matching(_ locale: Locale) -> Delimiter {
            locale.decimalSeparator == "," ? .semicolon : .comma
        }
    }

    /// Готовое содержимое файла: UTF-8 с BOM, иначе Excel показывает кириллицу кракозябрами.
    public static func data(
        for records: [ReadingHistoryRecord],
        delimiter: Delimiter = .matching(.current)
    ) -> Data {
        var data = Data([0xEF, 0xBB, 0xBF])
        data.append(Data(text(for: records, delimiter: delimiter).utf8))
        return data
    }

    public static func text(for records: [ReadingHistoryRecord], delimiter: Delimiter) -> String {
        let header = ["Начало", "Длительность (мин)", "Книга", "Автор"]
        var lines = [header.map { field($0, delimiter) }.joined(separator: delimiter.rawValue)]

        for record in records.sorted(by: { $0.startedAt < $1.startedAt }) {
            let fields = [
                startText(record),
                String(wholeMinutes(record.duration)),
                field(neutralizingFormula(record.bookTitle), delimiter),
                field(neutralizingFormula(record.bookAuthor), delimiter),
            ]
            lines.append(fields.joined(separator: delimiter.rawValue))
        }
        // CRLF — стандартный перевод строки для CSV (RFC 4180).
        return lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Местное время там, где началось чтение, в виде «2026-10-28 21:15».
    /// Такой формат Excel и Numbers распознают как дату при любом языке системы.
    static func startText(_ record: ReadingHistoryRecord) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: record.timeZoneIdentifier) ?? .current
        let parts = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: record.startedAt)
        return "\(pad(parts.year, 4))-\(pad(parts.month, 2))-\(pad(parts.day, 2)) "
            + "\(pad(parts.hour, 2)):\(pad(parts.minute, 2))"
    }

    /// Целые минуты с обычным округлением: 29 секунд → 0, 90 секунд → 2.
    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        // Потолок защищает от падения на заведомо битом значении.
        return Int(min(duration / 60, 1_000_000).rounded())
    }

    /// Поле в кавычках, если в нём есть разделитель, кавычка или перевод строки;
    /// кавычки внутри удваиваются (RFC 4180).
    private static func field(_ value: String, _ delimiter: Delimiter) -> String {
        let special = Set(("\"\r\n" + delimiter.rawValue).unicodeScalars)
        guard value.unicodeScalars.contains(where: special.contains) else { return value }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    /// Текст, начинающийся с = + - @, Excel выполнит как формулу.
    /// Апостроф в начале заставляет его показать текст как есть.
    private static func neutralizingFormula(_ value: String) -> String {
        guard let first = value.unicodeScalars.first,
              "=+-@\t\r".unicodeScalars.contains(first) else { return value }
        return "'" + value
    }

    private static func pad(_ number: Int?, _ width: Int) -> String {
        let digits = String(number ?? 0)
        return String(repeating: "0", count: max(0, width - digits.count)) + digits
    }
}
```

## 2. Кнопка «Поделиться» (`ReadingHistoryExportButton.swift`, в приложении)

```swift
import SwiftUI
import CoreTransferable
import UniformTypeIdentifiers

/// Файл CSV для системного меню «Поделиться». Собирается только при нажатии, не при каждой перерисовке экрана.
struct ReadingHistoryExport: Transferable, Sendable {
    let records: [ReadingHistoryRecord]

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            let day = Date.now.formatted(Date.ISO8601FormatStyle(timeZone: .current).year().month().day())
            // Отдельная папка на каждый экспорт: имя файла остаётся красивым и не конфликтует.
            let folder = URL.temporaryDirectory.appending(path: UUID().uuidString, directoryHint: .isDirectory)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let url = folder.appending(path: "История чтения \(day).csv")
            try ReadingHistoryCSV.data(for: export.records).write(to: url, options: .atomic)
            return SentTransferredFile(url)
        }
    }
}

struct ReadingHistoryExportButton: View {
    let sessions: [ReadingSession]

    var body: some View {
        ShareLink(
            item: ReadingHistoryExport(records: sessions.map { session in
                ReadingHistoryRecord(
                    startedAt: session.startedAt,
                    duration: session.duration,
                    timeZoneIdentifier: session.timeZoneIdentifier,
                    bookTitle: session.bookTitle,
                    bookAuthor: session.bookAuthor
                )
            }),
            preview: SharePreview("История чтения", image: Image(systemName: "tablecells"))
        ) {
            Label("Экспорт в CSV", systemImage: "square.and.arrow.up")
        }
        .disabled(sessions.isEmpty)
    }
}
```

