Без UI-фреймворков, поэтому файл можно положить в логический пакет рядом с `ReadingSession`.

```swift
import Foundation

/// Builds the reading-history CSV file that opens correctly in Excel and Numbers.
nonisolated enum ReadingHistoryCSV {
    /// `;` where the decimal separator is a comma (Russian and most European regions), `,` elsewhere:
    /// the same rule Excel uses to pick its list separator.
    static func separator(for locale: Locale) -> String {
        locale.decimalSeparator == "," ? ";" : ","
    }

    /// File bytes: UTF-8 with BOM (Excel needs it for Cyrillic), CRLF line endings, oldest session first.
    static func fileData(for sessions: [ReadingSession], separator: String) -> Data {
        let header = ["Начало", "Длительность (мин)", "Название", "Автор"].map(quoted)
        var lines = [header.joined(separator: separator)]
        var formatters: [String: DateFormatter] = [:]

        for session in sessions.sorted(by: { $0.startedAt < $1.startedAt }) {
            let formatter = formatters[session.timeZoneIdentifier] ?? makeFormatter(session.timeZoneIdentifier)
            formatters[session.timeZoneIdentifier] = formatter
            let fields = [
                formatter.string(from: session.startedAt),
                String(minutes(session.duration)),
                quoted(session.bookTitle),
                quoted(session.bookAuthor),
            ]
            lines.append(fields.joined(separator: separator))
        }

        let text = lines.joined(separator: "\r\n") + "\r\n"
        return Data([0xEF, 0xBB, 0xBF]) + Data(text.utf8)
    }

    /// Start time in the session's own time zone, in a form Excel and Numbers recognize as a date.
    private static func makeFormatter(_ timeZoneIdentifier: String) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        return formatter
    }

    private static func minutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// Always quotes, doubles inner quotes, and defuses text that a spreadsheet would run as a formula.
    private static func quoted(_ text: String) -> String {
        var value = text
        if let first = value.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            value = "'" + value
        }
        return "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }
}
```

